// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Easing,
  random,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type TierListProps = Record<string, any>;

const TierList: React.FC<TierListProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 8,
  listBgColor = "#ffffff",
  tiers = [
    {
      tierName: "Top Tier",
      tierColor: "#ff7b72",
      headerTextColor: "#ffffff",
      items: [
        { 
          image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/manus.png", 
          bgColor: "#ffffff" 
        },
      ],
    },
    {
      tierName: "Helpful",
      tierColor: "#ffb067",
      headerTextColor: "#ffffff",
      items: [
        { 
          image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/claude.webp", 
          bgColor: "#ffffff" 
        },
        { 
          image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/gemini.png", 
          bgColor: "#ffffff" 
        },
      ],
    },
    {
      tierName: "Decent",
      tierColor: "#ffd666",
      headerTextColor: "#000000",
      items: [
        { 
          image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/grok.webp", 
          bgColor: "#ffffff" 
        },
      ],
    },
    {
      tierName: "Waste of Time",
      tierColor: "#82d08a",
      headerTextColor: "#000000",
      items: [
        { 
          image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/qwen.jpeg", 
          bgColor: "#ffffff" 
        },
        { 
          image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/openai.png", 
          bgColor: "#ffffff" 
        },
        { 
          image: "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/llm_logos/deepseek.png", 
          bgColor: "#ffffff" 
        },
      ],
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const itemSize = 120;
  const rowHeight = 140;
  const rowGap = 12;
  const headerWidth = 240;
  const containerPadding = 8;
  const containerWidth = width * 0.9;
  const containerX = (width - containerWidth) / 2;
  const totalTiersHeight =
    tiers.length * rowHeight +
    Math.max(0, tiers.length - 1) * rowGap +
    containerPadding * 2;
  const containerY = (height - totalTiersHeight) / 2 - 80;

  const deckX = width / 2;
  const deckY = height - 120;
  const startX = deckX - itemSize / 2;
  const startY = deckY - itemSize / 2;

  // Flatten items to determine target positions
  const flatItems: any[] = [];
  let itemGlobalIndex = 0;
  tiers.forEach((tier, tierIndex) => {
    tier.items.forEach((item, itemIndex) => {
      flatItems.push({
        ...item,
        tierIndex,
        itemIndex,
        globalIndex: itemGlobalIndex,
        finalX:
          containerX +
          containerPadding +
          headerWidth +
          24 +
          itemIndex * (itemSize + 16),
        finalY:
          containerY +
          containerPadding +
          tierIndex * (rowHeight + rowGap) +
          (rowHeight - itemSize) / 2,
      });
      itemGlobalIndex++;
    });
  });

  const numItems = flatItems.length;
  const totalActiveFrames = durationInSeconds * fps - 30; // Reserve final second for hold
  const framesPerItem = Math.max(
    4,
    numItems > 0 ? Math.floor(totalActiveFrames / numItems) : 30
  );

  // Time slots per phase
  const p1 = Math.max(1, Math.floor(framesPerItem * 0.35));
  const p2 = Math.max(1, Math.floor(framesPerItem * 0.1));
  const p3 = Math.max(1, Math.floor(framesPerItem * 0.45));
  const p4 = Math.max(1, framesPerItem - p1 - p2 - p3);

  const getDeckPos = (globalIdx: number) => {
    const rX = (random(`deck-x-${globalIdx}`) - 0.5) * 10;
    const rY = (random(`deck-y-${globalIdx}`) - 0.5) * 10;
    // Stack items so the first one processed appears on top
    const offset = (numItems - 1 - globalIdx) * 3;
    return { x: startX - offset + rX, y: startY - offset + rY };
  };

  const getCursorState = (f: number) => {
    if (numItems === 0) return null;

    const lastItemFinishedFrame = numItems * framesPerItem;
    if (f >= lastItemFinishedFrame) {
      // Move cursor offscreen when done
      const offX = flatItems[numItems - 1].finalX + itemSize / 2;
      const offY = flatItems[numItems - 1].finalY + itemSize / 2;
      const finalCX = interpolate(
        f - lastItemFinishedFrame,
        [0, 15],
        [offX, offX + 150],
        { extrapolateRight: "clamp" }
      );
      const finalCY = interpolate(
        f - lastItemFinishedFrame,
        [0, 15],
        [offY, height + 150],
        { extrapolateRight: "clamp" }
      );
      return {
        x: finalCX,
        y: finalCY,
        scale: 1,
        isGrabbing: false,
        activeItemGlobalIndex: -1,
      };
    }

    const k = Math.floor(f / framesPerItem);
    const localFrame = f % framesPerItem;

    const currentDeckPos = getDeckPos(k);
    const targetDeckX = currentDeckPos.x + itemSize / 2;
    const targetDeckY = currentDeckPos.y + itemSize / 2;

    const prevDropX = k === 0 ? width / 2 + 100 : flatItems[k - 1].finalX + itemSize / 2;
    const prevDropY = k === 0 ? height + 100 : flatItems[k - 1].finalY + itemSize / 2;

    const targetX = flatItems[k].finalX + itemSize / 2;
    const targetY = flatItems[k].finalY + itemSize / 2;

    let cx = 0;
    let cy = 0;
    let scale = 1;
    let isGrabbing = false;

    if (localFrame < p1) {
      cx = interpolate(localFrame, [0, p1], [prevDropX, targetDeckX], {
        easing: Easing.out(Easing.quad),
      });
      cy = interpolate(localFrame, [0, p1], [prevDropY, targetDeckY], {
        easing: Easing.out(Easing.quad),
      });
    } else if (localFrame < p1 + p2) {
      cx = targetDeckX;
      cy = targetDeckY;
      const grabProgress = localFrame - p1;
      scale = interpolate(grabProgress, [0, p2], [1, 0.8]);
      isGrabbing = true;
    } else if (localFrame < p1 + p2 + p3) {
      const dragProgress = localFrame - (p1 + p2);
      cx = interpolate(dragProgress, [0, p3], [targetDeckX, targetX], {
        easing: Easing.inOut(Easing.quad),
      });
      cy = interpolate(dragProgress, [0, p3], [targetDeckY, targetY], {
        easing: Easing.inOut(Easing.quad),
      });
      scale = 0.8;
      isGrabbing = true;
    } else {
      cx = targetX;
      cy = targetY;
      const relProgress = localFrame - (p1 + p2 + p3);
      scale = interpolate(relProgress, [0, p4], [0.8, 1]);
      isGrabbing = false;
    }

    return {
      x: cx,
      y: cy,
      scale,
      isGrabbing,
      activeItemGlobalIndex: isGrabbing ? k : -1,
    };
  };

  const getItemPos = (globalIdx: number, f: number) => {
    const itemStartTime = globalIdx * framesPerItem;
    const deckPos = getDeckPos(globalIdx);

    if (f < itemStartTime + p1 + p2) {
      // Resting in deck
      return {
        x: deckPos.x,
        y: deckPos.y,
        scale: 1,
        visible: true,
        zIndex: numItems - globalIdx,
      };
    }

    if (f >= itemStartTime + p1 + p2 && f < itemStartTime + framesPerItem) {
      // Actively dragged or snapped directly in place during release
      const currentCursor = getCursorState(f);
      if (currentCursor && currentCursor.activeItemGlobalIndex === globalIdx) {
        return {
          x: currentCursor.x - itemSize / 2,
          y: currentCursor.y - itemSize / 2,
          scale: 1.1,
          visible: true,
          zIndex: 100,
        };
      }
    }

    // Placed - initiate drop bounce
    const dropFrame = Math.max(0, f - (itemStartTime + framesPerItem));
    const dropScale = spring({
      frame: dropFrame,
      fps,
      config: { damping: 12, stiffness: 120 },
    });

    return {
      x: flatItems[globalIdx].finalX,
      y: flatItems[globalIdx].finalY,
      scale: interpolate(dropScale, [0, 1], [1.1, 1]),
      visible: true,
      zIndex: 1,
    };
  };

  const cursor = getCursorState(frame);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Tier Board Container */}
      <div
        style={{
          position: "absolute",
          left: containerX,
          top: containerY,
          width: containerWidth,
          height: totalTiersHeight,
          display: "flex",
          flexDirection: "column",
          gap: rowGap,
          backgroundColor: listBgColor,
          borderRadius: 16,
          padding: containerPadding,
          boxShadow: "0px 10px 40px rgba(0,0,0,0.1)",
          boxSizing: "border-box",
        }}
      >
        {tiers.map((tier, tierIndex) => (
          <div
            key={`tier-${tierIndex}`}
            style={{
              display: "flex",
              height: rowHeight,
              width: "100%",
              backgroundColor: "rgba(0,0,0,0.03)",
              borderRadius: 12,
              boxShadow: "inset 0px 4px 10px rgba(0,0,0,0.05)",
              border: "1px solid rgba(0,0,0,0.05)",
            }}
          >
            {/* Header Block */}
            <div
              style={{
                width: headerWidth,
                height: "100%",
                flexShrink: 0,
                backgroundColor: tier.tierColor,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                textAlign: "center",
                padding: "0 16px",
                boxSizing: "border-box",
                lineHeight: 1.1,
                wordBreak: "break-word",
                fontWeight: 800,
                fontSize: 36,
                color: tier.headerTextColor,
                borderRight: "4px solid rgba(0,0,0,0.15)",
                borderTopLeftRadius: 12,
                borderBottomLeftRadius: 12,
                boxShadow: "inset -4px 0px 10px rgba(0,0,0,0.05)",
              }}
            >
              {tier.tierName}
            </div>
            {/* Drop Zone Area */}
            <div style={{ flex: 1 }} />
          </div>
        ))}
      </div>

      {/* Draggable Logos / Items */}
      {flatItems.map((item) => {
        const pos = getItemPos(item.globalIndex, frame);
        if (!pos.visible) return null;

        return (
          <div
            key={`item-${item.globalIndex}`}
            style={{
              position: "absolute",
              left: pos.x,
              top: pos.y,
              width: itemSize,
              height: itemSize,
              backgroundColor: item.bgColor,
              borderRadius: 24,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: "0px 8px 20px rgba(0,0,0,0.15)",
              border: "2px solid rgba(0,0,0,0.05)",
              transform: `scale(${pos.scale})`,
              zIndex: pos.zIndex,
              overflow: "hidden",
            }}
          >
            <Img
              src={item.image}
              style={{
                width: "70%",
                height: "70%",
                objectFit: "contain",
              }}
            />
          </div>
        );
      })}

      {/* Simulated Cursor */}
      {cursor && (
        <div
          style={{
            position: "absolute",
            left: cursor.x,
            top: cursor.y,
            transform: `scale(${cursor.scale})`,
            transformOrigin: "0 0",
            zIndex: 1000,
            filter: "drop-shadow(0px 8px 12px rgba(0,0,0,0.2))",
            pointerEvents: "none",
          }}
        >
          <svg
            width="48"
            height="48"
            viewBox="0 0 24 24"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M4 2 L4 22 L10 16 L14 23 L17 21 L13 15 L19 15 Z"
              fill="white"
              stroke="black"
              strokeWidth="1.5"
              strokeLinejoin="round"
            />
          </svg>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default TierList;